// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    Recorder recorder;

    function setUp() public {
        recorder = new Recorder();
        c = new PoCGame(address(recorder), 1000000000000000000);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(this), amount);

        // Reference must revert here because openToPublic == false.
        // Mutant skips the guard and forwards ETH to the whale recorder.
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("donate()"));

        bool leaked = recorder.totalReceived() > 0;
        assertTrue(!ok || !leaked);
    }
}

contract Recorder {
    uint256 public totalReceived;
    fallback() external payable { totalReceived += msg.value; }
    receive() external payable { totalReceived += msg.value; }
}
